import html,re
E=lambda x:html.escape(x,quote=True)
def md_html(md):
 out=[]; table=[]; listing=False
 def close():
  nonlocal listing
  if listing:out.append('</ul>');listing=False
 def flush():
  if table:
   out.append('<div class="policy-table"><table>')
   for i,row in enumerate(table):
    tag='th' if i==0 else 'td';out.append('<tr>'+''.join(f'<{tag}>{E(c)}</{tag}>' for c in row)+ '</tr>')
   out.append('</table></div>');table.clear()
 for line in md.splitlines():
  line=line.strip()
  if line.startswith('|'):
   close();cells=[c.strip() for c in line.strip('|').split('|')]
   if not all(re.fullmatch(r'[-: ]+',c) for c in cells):table.append(cells)
   continue
  flush()
  if line.startswith('- '):
   if not listing:out.append('<ul>');listing=True
   out.append('<li>'+E(line[2:])+'</li>');continue
  close()
  if not line:continue
  if line.startswith('#'):
   level=min(3,len(line)-len(line.lstrip('#')));out.append(f'<h{level}>'+E(line.lstrip('# '))+f'</h{level}>')
  elif line.startswith('>'):out.append('<p class="notice">'+E(line.lstrip('> '))+'</p>')
  else:out.append('<p>'+E(line)+'</p>')
 close();flush();return ''.join(out)
def choice(label,key,opts=('가능','불가')):
 return f'<label>{label}<select name="{key}"><option value="">확인 필요 / 미입력</option><option value="true">{opts[0]}</option><option value="false">{opts[1]}</option></select></label>'
common=''.join(choice(l,k,o) for l,k,o in [('대형견 가능','petSizeLarge',('가능','불가')),('실내 동반','indoor',('가능','불가')),('주차','parking',('가능','불가')),('영업 여부','operating',('영업 중','폐업'))])
extra=''.join(choice(l,k) for l,k in [('소형견','petSizeSmall'),('중형견','petSizeMedium'),('실외 동반','outdoor'),('바닥에 내려놓기','floorAllowed'),('테라스','terrace')])+choice('이동장 필요','carrierRequired',('필요','불필요'))+choice('접종 확인 필요','vaccinationCheck',('필요','불필요'))
form='''<h1>사장님 무료 입점 신청 / 정보 수정 제안 / 폐업 신고 / 출시 알림</h1><p class="notice">검수용: 실제 개인정보를 입력하지 마세요. 서버 접수 없이 입력한 내용을 JSON으로 저장하는 시연입니다. 정책은 초안입니다.</p><form id="intake" class="panel intake" name="eodigagae-intake" method="POST" data-live="false"><input type="hidden" name="formKind" value="eodigagae-intake"><p hidden><label>입력하지 마세요<input name="_gotcha" tabindex="-1" autocomplete="off"></label></p><input type="hidden" name="policyVersion" value="draft-2026-11-25"><input type="hidden" name="createdAt"><label>신청 유형<select name="type"><option value="owner">사장님 무료 입점 신청</option><option value="correction">정보 수정 제안</option><option value="closure">폐업 신고</option><option value="launch">출시 알림</option><option value="pricing">유료상품 문의</option></select></label><fieldset id="placeFields"><legend>장소 정보</legend><label>업체 ID<input name="placeId"></label><label>업체명<input name="name"></label><label>주소<input name="address"></label><label>근거 URL<input type="url" name="source"></label><label>제보·동반 조건<textarea name="details" rows="3"></textarea></label>'''+common+'''</fieldset><fieldset id="ownerFields"><legend>입점 추가 정보</legend><label>담당자 이름<input name="contactName"></label><label>연락처<input type="tel" name="phone"></label>'''+extra+'''<label>무게 제한<input name="weightLimit"></label><label>추가 요금<input name="petFee"></label><label>메뉴 및 가격<textarea name="menu"></textarea></label><label>사진 이용 권한 (사진 업로드 미지원)<textarea name="imageRights"></textarea></label><p>동반출입 준비 및 물품구입비 지원 제도는 관할 기관의 최신 공고를 확인하세요.</p></fieldset><fieldset id="pricingFields"><legend>광고 상담 정보</legend><label>희망 상품<select name="plan"><option value="premium">프리미엄 매장</option><option value="regional">지역 상단 광고</option><option value="marketing">마케팅 패키지</option></select></label><label>희망 광고 지역<input name="adRegion"></label></fieldset><label>이메일 (선택, 출시 알림은 이메일 또는 휴대전화 중 하나 필수)<input type="email" name="email"></label><label id="launchPhoneField" hidden>출시 알림 휴대전화 (이메일 또는 휴대전화 중 하나)<input name="launchPhone" type="tel" disabled></label><p id="consentPurpose"></p><label><input type="checkbox" required name="privacyConsent" value="yes"> (필수) 개인정보 수집·이용 및 국외 이전에 동의합니다. <a href="/privacy/">개인정보처리방침(초안)</a></label><p class="muted">국외 이전에 동의하지 않으면 온라인 신청이 제한됩니다. 이메일 신청: <span data-contact>[대표 이메일 확정 후 안내]</span></p><button type="submit" class="btn primary" disabled data-submit>검수용 JSON 저장 (접수 아님)</button><p id="result" role="status"></p></form><script src="/intake.js" defer></script>'''
intake_js=r'''"use strict";const f=document.querySelector('#intake'),q=new URLSearchParams(location.search),kinds=['owner','correction','closure','launch','pricing'];if(kinds.includes(q.get('type')))f.elements.type.value=q.get('type');if(/^[pf]\d+$/.test(q.get('place')||''))f.elements.placeId.value=q.get('place');if(q.get('name'))f.elements.name.value=q.get('name');if(['premium','regional','marketing'].includes(q.get('plan')))f.elements.plan.value=q.get('plan');function update(){const t=f.elements.type.value;for(const [id,show] of [['placeFields',t!=='launch'],['ownerFields',t==='owner'||t==='pricing'],['pricingFields',t==='pricing']]){const b=document.getElementById(id);b.hidden=!show;b.disabled=!show}const owner=t==='owner',pricing=t==='pricing',report=t==='correction'||t==='closure';const lp=f.elements.launchPhone;lp.disabled=t!=='launch';lp.closest('label').hidden=t!=='launch';for(const k of ['name','address','contactName','phone','details','placeId','email','adRegion'])f.elements[k].required=({name:owner||pricing,address:owner,contactName:owner||pricing,phone:owner||pricing,details:t!=='launch',placeId:report,email:false,adRegion:pricing})[k];for(const k of ['petSizeSmall','petSizeMedium','outdoor','floorAllowed','terrace','carrierRequired','vaccinationCheck','weightLimit','petFee','menu','imageRights']){f.elements[k].disabled=!owner;f.elements[k].closest('label').hidden=!owner}for(const k of ['petSizeLarge','indoor','parking','operating','source','address','placeId','name']){const hide=(pricing&&k!=='name')||(report&&['address','name'].includes(k));f.elements[k].disabled=hide;f.elements[k].closest('label').hidden=hide}if(t==='closure'&&!f.elements.operating.value)f.elements.operating.value='false';const notice={launch:'수집: 이메일 또는 휴대전화 / 목적: 출시 안내 / 보유: 발송 후 즉시 파기',owner:'수집: 상호, 담당자, 연락처, 주소, 동반 조건, 선택 이메일 및 메모 / 목적: 입점 심사·등록 / 보유: 해지·반려 후 6개월',pricing:'수집: 상호, 담당자, 연락처, 희망 상품·지역, 문의 내용, 선택 이메일 / 목적: 광고 상담 / 보유: 미계약 상담 종료 후 3개월, 계약 고객은 계약 종료 후 5년(법령 및 계약 기준)',correction:'수집: 업체 ID, 수정 내용·동반 조건, 선택 근거 URL·이메일 / 목적: 정보 정정 / 보유: 처리 후 3개월',closure:'수집: 업체 ID, 신고 내용·영업 여부, 선택 근거 URL·이메일 / 목적: 폐업 반영 / 보유: 처리 후 3개월'};document.getElementById('consentPurpose').textContent=notice[t]+' / '+f.dataset.processorNotice}f.elements.type.onchange=update;update();f.querySelector('[data-submit]').disabled=false;f.addEventListener('submit',async e=>{e.preventDefault();if(f.elements.type.value==='launch'&&!f.elements.email.value.trim()&&!f.elements.launchPhone.value.trim()){document.getElementById('result').textContent='이메일 또는 휴대전화 중 하나를 입력해 주세요.';return;}if(!f.reportValidity()||!f.elements.privacyConsent.checked)return;const live=f.dataset.live==='true'&&location.protocol==='https:'&&!window.EG_PREVIEW_DATA;const result=document.getElementById('result'),button=f.querySelector('button[type=submit]');if(f.dataset.live==='true'&&!live){result.textContent='HTTPS 배포 사이트에서만 실제 접수 가능합니다.';return;}f.elements.createdAt.value=new Date().toISOString();if(live){button.disabled=true;result.textContent='접수 중…';try{const response=await fetch(f.action,{method:'POST',headers:{'Accept':'application/json','Content-Type':'application/x-www-form-urlencoded'},body:new URLSearchParams(new FormData(f)).toString(),credentials:'omit',redirect:'error'});if(!response.ok)throw new Error('HTTP '+response.status);result.textContent='신청 전송 완료. 운영자 검토 후 처리됩니다.';f.reset();update();}catch(err){result.textContent='전송 결과를 확인하지 못했습니다. 잠시 후 다시 시도하거나 운영자에게 문의하세요.';}finally{button.disabled=false;}return;}const data=Object.fromEntries(new FormData(f));for(const k of ['petSizeSmall','petSizeMedium','petSizeLarge','floorAllowed','terrace','carrierRequired','vaccinationCheck','indoor','outdoor','parking','operating'])if(k in data)data[k]=data[k]==='true'?true:data[k]==='false'?false:null;delete data['_gotcha'];data.privacyConsent=true;data.policyVersion=f.elements.policyVersion.value;data.createdAt=new Date().toISOString();const u=URL.createObjectURL(new Blob([JSON.stringify(data,null,2)],{type:'application/json'})),a=document.createElement('a');a.href=u;a.download='eodigagae-'+data.type+'.json';a.click();setTimeout(()=>URL.revokeObjectURL(u),1000);document.getElementById('result').textContent='파일 저장 요청 완료. 운영자에게 전송되지 않았습니다.'});'''

